 * Invoke or update a ref, depending on whether it is a function or object ref.
 * If a function ref returns a cleanup function, it is stored on the ref and
 * invoked (instead of calling the ref with `null`) when the ref is detached.
 * @param {Ref<any>} ref
 * @param {any} value
 * @param {VNode} vnode
 */
export function applyRef(ref, value, vnode) {
	let error = null;
	try {
		if (typeof ref == 'function') {
			// When a ref is detached (`value == null`) and the ref callback
			// returned a cleanup function, invoke that cleanup instead of
			// calling the ref callback with `null`.
			let cleanup = value == null ? ref._cleanup : null;
			if (cleanup != null) {
				ref._cleanup = undefined;
				cleanup();
			} else {
				let result = ref(value);
				ref._cleanup = typeof result == 'function' ? result : undefined;
			}
		} else {
			ref.current = value;
		}
	} catch (e) {
		error = e;
	}

